param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Polygon([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
function Concat($objects){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($one in $objects){[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{if($null-ne$combined){$combined.Dispose()}}};Write-Output -NoEnumerate $all}

$temp=Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s48-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true)
$recordType=$assembly.GetType('HalconWinFormsDemo.Models.VmImageBatchTraceRecord',$true);$itemType=$assembly.GetType('HalconWinFormsDemo.Models.VmImageBatchTraceItem',$true);$toolResultType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceToolResultData',$true);$outputType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceToolOutputData',$true);$layerType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceLayerSnapshotData',$true)
$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}
function Output([string]$port,[string]$type,[string]$value){$o=[Activator]::CreateInstance($outputType);$o.PortName=$port;$o.DisplayName=$port;$o.DataType=$type;$o.Value=$value;$o.Normalize(0);$o}
function ToolResult([string]$id,[string]$name,[string]$code,[double]$elapsed,$outputs){$r=[Activator]::CreateInstance($toolResultType);$r.ToolId=$id;$r.ToolName=$name;$r.ToolType='测试工具';$r.ResultCode=$code;$r.ElapsedMilliseconds=$elapsed;$r.Outputs=New-Object "System.Collections.Generic.List[$outputType]";foreach($o in $outputs){$r.Outputs.Add($o)};$r.Normalize(0);$r}

# A: align by ToolId, detect added/missing/result/output/elapsed, numeric delta, filters, legacy degradation and dual-side layer linkage.
$baseline=[Activator]::CreateInstance($itemType);$baseline.FileName='baseline.png';$baseline.ResultCode='OK';$baseline.ToolResults=New-Object "System.Collections.Generic.List[$toolResultType]"
$baseline.ToolResults.Add((ToolResult 'T1' 'Locate' 'OK' 5 @((Output 'Score' 'Number' '10'),(Output 'Mode' 'String' 'A'))));$baseline.ToolResults.Add((ToolResult 'T2' 'Judge' 'OK' 2 @((Output 'Value' 'Number' '1'))));$baseline.ToolResults.Add((ToolResult 'T3' 'Removed' 'NG' 1 @()))
$comparison=[Activator]::CreateInstance($itemType);$comparison.FileName='comparison.png';$comparison.ResultCode='NG';$comparison.ToolResults=New-Object "System.Collections.Generic.List[$toolResultType]"
$comparison.ToolResults.Add((ToolResult 'T1' 'Locate' 'OK' 7 @((Output 'Score' 'Number' '13.5'),(Output 'Mode' 'String' 'B'))));$comparison.ToolResults.Add((ToolResult 'T2' 'Judge' 'NG' 2 @((Output 'Value' 'Number' '1'))));$comparison.ToolResults.Add((ToolResult 'T4' 'Added' 'OK' 3 @()))
$mainType.GetField('historicalBatchItem',$private).SetValue($window,$baseline);$mainType.GetField('historicalComparisonBatchItem',$private).SetValue($window,$comparison);$mainType.GetField('historicalToolComparisonMode',$private).SetValue($window,$true)
(Field 'HistoricalToolComparisonSearchTextBox').Text='';(Field 'HistoricalToolComparisonFilterComboBox').SelectedValue='All';$mainType.GetMethod('RefreshHistoricalToolComparison',$private).Invoke($window,@())|Out-Null
$diffs=Field 'historicalToolDifferences';Assert($diffs.Count-eq4) 'ToolId alignment did not produce four stable rows';Assert(($diffs|Where-Object ToolId -eq T1).ChangeType-eq'Output') 'Number/String output difference missing';Assert(($diffs|Where-Object ToolId -eq T1).OutputDifferences-match '3.5') 'Numeric delta not shown';Assert(($diffs|Where-Object ToolId -eq T2).ChangeType-eq'Result') 'Result-code change missing';Assert(($diffs|Where-Object ToolId -eq T3).ChangeType-eq'Missing') 'Missing tool not detected';Assert(($diffs|Where-Object ToolId -eq T4).ChangeType-eq'Added') 'Added tool not detected'
(Field 'HistoricalToolComparisonSearchTextBox').Text='Locate';(Field 'HistoricalToolComparisonFilterComboBox').SelectedValue='Output';$mainType.GetMethod('RefreshHistoricalToolComparison',$private).Invoke($window,@())|Out-Null;Assert((Field 'HistoricalToolDifferenceList').Items.Count-eq1) 'Difference search/filter failed'
$legacy=[Activator]::CreateInstance($itemType);$legacy.ToolResults=New-Object "System.Collections.Generic.List[$toolResultType]";$mainType.GetField('historicalComparisonBatchItem',$private).SetValue($window,$legacy);$mainType.GetMethod('RefreshHistoricalToolComparison',$private).Invoke($window,@())|Out-Null;Assert((Field 'HistoricalToolComparisonStateText').Text-match '旧记录只读降级') 'Legacy comparison did not degrade visibly'
$mainType.GetField('historicalComparisonBatchItem',$private).SetValue($window,$comparison);(Field 'HistoricalToolComparisonSearchTextBox').Text='';(Field 'HistoricalToolComparisonFilterComboBox').SelectedValue='All';$mainType.GetMethod('RefreshHistoricalToolComparison',$private).Invoke($window,@())|Out-Null
$historyLayerType=$mainType.GetNestedType('HistoricalLayerSnapshot',[Reflection.BindingFlags]'NonPublic');$baselineLayers=Field 'historicalLayers';$comparisonLayers=Field 'historicalComparisonLayers';$baselineLayers.Clear();$comparisonLayers.Clear();foreach($target in @(@($baselineLayers,'T1'),@($baselineLayers,'OTHER'),@($comparisonLayers,'T1'),@($comparisonLayers,'OTHER'))){$meta=[Activator]::CreateInstance($layerType);$meta.ToolId=$target[1];$meta.ToolName=$target[1];$meta.PortName='XLD';$meta.DataType='XLD';$layer=[Activator]::CreateInstance($historyLayerType,$true);$historyLayerType.GetProperty('Metadata').SetValue($layer,$meta,$null);$historyLayerType.GetProperty('IsVisible').SetValue($layer,$true,$null);$target[0].Add($layer)}
$selectedBefore=(Field 'FlowToolList').SelectedItem;$button=New-Object Windows.Controls.Button;$button.Tag=($diffs|Where-Object ToolId -eq T1).PSObject.BaseObject;$mainType.GetMethod('HistoricalToolDifferenceLinkButton_Click',$private).Invoke($window,[object[]]@($button.PSObject.BaseObject,$null))|Out-Null;Assert($baselineLayers[0].IsVisible-and-not$baselineLayers[1].IsVisible-and$comparisonLayers[0].IsVisible-and-not$comparisonLayers[1].IsVisible) 'Dual-side layer linkage failed';Assert([object]::ReferenceEquals($selectedBefore,(Field 'FlowToolList').SelectedItem)) 'Comparison changed live tool selection'
foreach($name in @('HistoricalComparisonCandidateComboBox','HistoricalToolComparisonPanel','HistoricalToolComparisonSearchTextBox','HistoricalToolComparisonFilterComboBox','HistoricalToolDifferenceList')){Assert($null-ne(Field $name)) "$name missing"}

# B: real smallest_rectangle1_xld/compactness_xld, inclusive bounds, skip policy, ownership, lifecycle, recipe and downstream.
$filterKind=[Enum]::Parse($kindType,'XldBoundingCompactnessFilter');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($filterKind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($filterKind));Assert(($inputs|Where-Object PortName -eq XLD).Count-eq1) 'Typed XLD input missing';Assert(($outputs|Where-Object PortName -eq MeanCompactness).DataType-eq'Number'-and($outputs|Where-Object PortName -eq OriginalIndices).DataType-eq'String') 'Typed geometry outputs missing'
$rect=Polygon ([double[]]@(0,0,10,10,0)) ([double[]]@(0,20,20,0,0));$square=Polygon ([double[]]@(0,0,10,10,0)) ([double[]]@(0,10,10,0,0));$open=Polygon ([double[]]@(0,0,10,10)) ([double[]]@(0,20,20,0));$bowtie=Polygon ([double[]]@(0,10,0,10,0)) ([double[]]@(0,10,10,0,0));$degenerate=Polygon ([double[]]@(0,0,0,0)) ([double[]]@(0,5,10,0));$input=Concat @($rect,$square,$open,$bowtie,$degenerate);foreach($x in @($rect,$square,$open,$bowtie,$degenerate)){$x.Dispose()}
$flow=Field 'flowTools';$filter=Tool XldBoundingCompactnessFilter 'S48 Bounding Compactness';$flow.Add($filter);$run=$mainType.GetMethod('RunXldBoundingCompactnessFilterTool',$private);function RunFilter($x){try{$run.Invoke($window,[object[]]@($filter,$x.PSObject.BaseObject))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
try{$filter.Parameters.XldBoundingWidthMinimum=10;$filter.Parameters.XldBoundingWidthMaximum=20;$filter.Parameters.XldBoundingHeightMinimum=10;$filter.Parameters.XldBoundingHeightMaximum=10;$filter.Parameters.XldCompactnessMinimum=1;$filter.Parameters.XldCompactnessMaximum=2;$filter.Parameters.XldBoundingClosureTolerance=0;$result=RunFilter $input;Assert($result.ResultCode-eq'OK'-and(Out $filter OriginalIndices)-eq'[1,2]') 'Inclusive width/height/compactness selection failed';Assert([int](Out $filter InputOpenCount)-eq1-and[int](Out $filter SelfIntersectingCount)-eq1-and[int](Out $filter DegenerateCount)-eq1) 'Open/self-intersecting/degenerate skip policy failed';Assert([Math]::Abs([double](Out $filter MinWidth)-10)-lt.0001-and[Math]::Abs([double](Out $filter MaxWidth)-20)-lt.0001-and[double](Out $filter MeanCompactness)-gt1) 'Geometry statistics failed';$old=Out $filter XLD;$filter.Parameters.XldBoundingWidthMinimum=20;$filter.Parameters.XldBoundingWidthMaximum=20;RunFilter $input|Out-Null;Assert((Out $filter OriginalIndices)-eq'[1]'-and$old.IsDisposed) 'Exact boundary or old snapshot release failed';[HalconDotNet.HTuple]$count=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$count);Assert($count.I-eq5) 'Upstream ownership changed'}finally{$input.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$emptyResult=RunFilter $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $filter ContourCount)-eq0) 'Empty input semantics failed'}finally{$empty.Dispose()}
$filter.Parameters.XldBoundingWidthMinimum=20;$filter.Parameters.XldBoundingWidthMaximum=10;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid width range accepted';$filter.Parameters.XldBoundingWidthMinimum=0;$filter.Parameters.XldBoundingWidthMaximum=100;$filter.Parameters.XldCompactnessMinimum=.5;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid compactness range accepted';$filter.Parameters.XldCompactnessMinimum=1;$filter.Parameters.XldBoundingClosureTolerance=-1;Assert(-not[string]::IsNullOrWhiteSpace($filter.Parameters.Validate($filterKind))) 'Invalid closure tolerance accepted'
$producer=Tool XldPointClosureFilter 'Geometry Source';$chain=Tool XldBoundingCompactnessFilter 'Geometry Chain';$judge=Tool NumericJudge 'Geometry Count Judge';$chain.Parameters.XldBoundingWidthMinimum=9;$chain.Parameters.XldBoundingWidthMaximum=21;$chain.Parameters.XldBoundingHeightMinimum=9;$chain.Parameters.XldBoundingHeightMaximum=11;$chain.Parameters.XldCompactnessMinimum=1;$chain.Parameters.XldCompactnessMaximum=2;$chain.Parameters.XldBoundingClosureTolerance=0;$chain.SetInputBinding('XLD',$producer.ToolId,'XLD');$judge.SetInputBinding('Value',$chain.ToolId,'ContourCount');$judge.InputToolId=$chain.ToolId;$judge.InputPortName='ContourCount';$judge.NumericLowerLimit=2;$judge.NumericUpperLimit=2;$flow.Add($producer);$flow.Add($chain);$flow.Add($judge);$r1=Polygon ([double[]]@(0,0,10,10,0)) ([double[]]@(0,20,20,0,0));$r2=Polygon ([double[]]@(0,0,10,10,0)) ([double[]]@(0,10,10,0,0));$chainInput=Concat @($r1,$r2);$r1.Dispose();$r2.Dispose();try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($chainInput.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$chainInput.Dispose()};$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$execute.Invoke($window,[object[]]@($chain,'S48 chain'))|Out-Null;$execute.Invoke($window,[object[]]@($judge,'S48 chain'))|Out-Null;Assert($chain.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Real XLD/Number downstream chain failed';$released=Out $producer XLD;$released.Dispose();$failed=$false;try{$execute.Invoke($window,[object[]]@($chain,'released upstream'))|Out-Null}catch{$failed=$true};Assert $failed 'Released upstream XLD was accepted'
$filter.Parameters.XldBoundingWidthMinimum=10;$filter.Parameters.XldBoundingWidthMaximum=20;$filter.Parameters.XldBoundingHeightMinimum=10;$filter.Parameters.XldBoundingHeightMaximum=10;$filter.Parameters.XldCompactnessMinimum=1;$filter.Parameters.XldCompactnessMaximum=2;$filter.Parameters.XldBoundingClosureTolerance=0;(Field 'FlowToolList').SelectedItem=$filter;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($filter))|Out-Null;Assert((Field 'DockXldBoundingCompactnessFilterPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldBoundingWidthMinimumTextBox').Text-eq'10') 'Dock configuration synchronization failed'
$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$filter.ToolId}|Select-Object -First 1;Assert($saved.Parameters.XldBoundingWidthMinimum-eq10-and$saved.Parameters.XldCompactnessMaximum-eq2-and$saved.Parameters.XldBoundingClosureTolerance-eq0) 'Recipe persistence failed'

$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S48 historical tool comparison and HALCON XLD bounding/compactness filter smoke tests passed.'
